    S den=radius+sf::exact(p.parameters[7]);Q lo=sf::lower(den);need(lo>0,"original density r+epsilon complex pole not excluded");Q taper=Q(p.parameters[8]),inner=exponent_upper(sf::upper(S(2)*(radius-sf::exact(p.parameters[4]))/S(taper))),outer=exponent_upper(sf::upper(S(2)*(radius-sf::exact(p.parameters[5]))/S(taper)));need(inner<1&&outer<1,"original logistic density poles not excluded on complex domain");Q gate=sf::mul(sf::quotient(inner,mf::FP<Q>::down(Q(1)-inner)),sf::quotient(Q(1),mf::FP<Q>::down(Q(1)-outer)));return sf::add(Q(p.parameters[6]),sf::mul(sf::quotient(Q(p.parameters[9]),lo),gate));
